            raise TypeError('Protocol version must be passed in a tuple')

        supported_version_slots = {}

        for version in cls._version_info:
            if version <= (3, 5):
                supported_version_slots[version] = cls.ProtocolHandler3_5

        if protocol_version:
            if protocol_version not in supported_version_slots:
                supported_version_slots[protocol_version] = cls.ProtocolHandlerUnknownVersion

        return supported_version_slots
