            return {v: cls.get_handler_class(v) for v in cls.supported_protocols}
        elif isinstance(protocol_version, tuple):
            return {protocol_version: cls.get_handler_class(protocol_version)} if protocol_version in cls.supported_protocols else {}
        else:
