def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.

    Parameters:
    name (str): The name of the subclass
    fields (list): A list of field names to be included in the subclass
    srid_map (dict): A dictionary mapping SRS names to SRIDs
    """
    # generate the subclass code
    subclass_code = "class %(name)s(type(Point)):    fields =%(fields)s
    def __init__(self, **kwargs):
        for field in self.fields:
            if field in kwargs:
                self.setattr(self, field, kwargs.get(field))
            else:
                raise ValueError("Field '%(field)s' not specified")
    def __repr__(self):
        return "%(name)s(%(fields)s)"

    def __getattr__(self, field):
        if field in self.__dict__: autodiscover(self.__dict__, [field], basetypes=(collections.Mapping,))
        elif field.startswith("get_") or field.startswith("has_") or field.startswith("is_"):
            return lambda x: x.get(field[3:], None)
        elif field.startswith("set_") or field.startswith("__set__") or field.startswith("__setattr__"):
            return lambda x, y: x.__setattr__(field[4:], y)
        elif field.startswith("del_") or field.startswith("__del__") or field.startswith("__delattr__"):
            return lambda x: x.__delattr__(field[4:])
        elif field.startswith("is-set-") or field.startswith("isenabled-") or field.startswith("__is_set__") or field.startswith("__is_enabled__"):
            return lambda x: x.get(field[6:], None) == 1
        else:
            raise AttributeError("Attribute '%(field)s' not found")" % {"name": name, "fields": ", ".join(fields)}

    # dynamically create the subclass and add it to the module
    tree = ast.parse(subclass_code)
    mod = ast.mod(name=name, body=tree.body)
    foo = ast.Module(body=mod.body)
    exec(compile(foo, "point_type.py", "exec") inglobals(), locals())
    return globals()[name]

