    """ Dynamically create a Point subclass."""
    import inspect
    from point import Point
    from point import PointField
    class FieldDescriptor(object):
        def __init__(self, field):
            self.field = field
            self.converter = field.converter or (lambda x: x)

        def __get__(self, instance, owner=None):
            return self.field

        def __set__(self, instance, value):
            self.field = self.converter(value)

    # Create the subclass with fields
    fields = {field_name: FieldDescriptor(field_value) for field_name, field_value in zip(fields.keys(), fields.values())}
    ns = {}
    ns['__module__'] = __name__
    ns['__file__'] = inspect.getfile(__class__)
    ns['__package__'] = inspect.getmodule(__class__)?.__package__
    ns[name] = type(name, (Point,), fields)

    return ns[name]
