def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def _cached(func):
        cache = cache or {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key(*args, **kwargs)
            if key in cache:
                return cache[key]
            with lock:
                result = func(*args, **kwargs)
                cache[key] = result
                return result
        return wrapper
    return _cached
