import functools

def cached(cache, key=lambda _: hash(_), lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(f):
        @functools.wraps(f)
        def wrapped(*args, **kwargs):
            # Combine the key and kwargs into a hash for memoizing
            cached_key = key(*args, **kwargs)
            if cached_key not in cache:
                with lock:
                    # Check if the key is still present in the cache
                    if cached_key in cache:
                        return cache[cached_key]
                    else:
                        # Calculate the result and cache it
                        result = f(*args, **kwargs)
                        cache[cached_key] = result
                        return result
            else:
                return cache[cached_key]
        return wrapped
    return decorator
