def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = classes[:]  # Defensive copy to protect against unintended modifications
    for base in classes:
        for other in classes:
            if base != other:
                bases.remove(other)
                break
    return bases

