    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, Declaration):
        sequence = Declaration(sequence)

    if not output:
        output = Declaration()

    for arg in sequence.args:
        if isinstance(arg, Declaration):
            output.args.append(arg)
        elif isinstance(arg, tuple):
            output.args.extend(arg)
        elif isinstance(arg, Interface):
            output.add_interface(arg)
        else:
            output.args.append(IndividialInterface(arg))

