def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    from collections import deque

    if output is None:
        output = deque()

    stack = deque([sequence])
    while stack:
        node = stack.popleft()

        if isinstance(node, str) and node in {'Declarations', 'Tuple'}:
            output.appendleft(node)
        elif isinstance(node, Declarion):
            output.appendleft(type(node))
        elif isinstance(node, tuple):
            for elem in node:
                stack.append(elem)
        elif isinstance(node, Interface):
            output.appendleft(node)
        elif isinstance(node, ImplementsSpec):
            output.appendleft(node.hash)
        else:
            raise ValueError(f"Unsupported declaration argument type: {type(node)}")

    return list(output)
```

```python
def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if sequence is None:
        return ""

    normalized = ""
    for arg in sequence:
        if isinstance(arg, Declaration):
            normalized += arg.__name__
        elif isinstance(arg, (tuple, list)):
            normalized += "("
            normalized += ", ".join(_normalizeargs(arg) for arg in arg)
            normalized += ")"
        elif isinstance(arg, Interface):
            if output:
                normalized += arg.__name__
            else:
                normalized += "Interface(" + arg.__name__ + ")"
        elif isinstance(arg, implementsSpec):
            if output:
                normalized += arg.classname
            else:
                normalized += "Spec Implements(" + arg.classname + ")"
        else:
            if output:
                normalized += str(arg)
            else:
                normalized += str(arg.__name__)

    return normalized

