    """
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}

    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif isinstance(value, dict):
            if key not in result or not all(_get_all(subvalue) == _get_all(value[key]) for subvalue in value:
                result[key] = _itemwise_difference(value, d2.get(key), key, level - 1)
    return result


def _get_all(value):
    if isinstance(value, dict):
        return list(itertools.chain.from_iterable(_get_all(subvalue) for subvalue in value.values()))
    return [value]


def _itemwise_difference(value1, value2, key, level):
    if isinstance(value1, dict) and isinstance(value2, dict):
        result = {}
        for subkey, subvalue1 in value1.items():
            subkey = f"{key}.{subkey}" if key else subkey
            if subkey not in value2:
                result[subkey] = subvalue1
            elif isinstance(subvalue1, dict) and isinstance(value2[subkey], dict):
                result[subkey] = _itemwise_difference(subvalue1, value2[subkey], subkey, level - 1)
            elif subvalue1 != value2[subkey]:
                result[subkey] = value1[subkey] if level == 0 else value2[subkey]
        return result
    return value1 if isinstance(value1, dict) else value2
