def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    regex_patterns = {
        key: re.compile(value) for key, value in labels.items() if isinstance(value, str) and value.startswith("$")
    }
    non_regex_additional_keys = [k for k, v in labels.items() if isinstance(v, str) and not any(v.startswith("$" + p) for p in regex_patterns)]
    try:
        for k, v in labels.items():
            if isinstance(v, list):
                for part in v:
                    if isinstance(part, str) and part in regex_patterns.values():
                        raise ValidationError({"[{}]".format(regex_patterns.values()): "expected string or bytes-like object"})
            elif isinstance(v, str) and v in regex_patterns.values():
                raise ValidationError({"[{0}]".format(v): "expected string or bytes-like object"})
            elif k in regex_patterns.keys():
                if not regex_patterns[k].match(v):
                    raise ValidationError({"[{0}]".format(k): "expected string or bytes-like object"})
            elif k in non_regex_additional_keys:
                if not isinstance(v, str):
                    raise ValidationError({"[{0}]": "expected string or bytes-like object"})
    except ValidationError as err:
        raise ValidationError(err.messages)
