from typing import AnyStr, Union, Sequence, Tuple, Iterable, Dict

class SQLParams:
    """SQL parameter style.
    """
    IN_STYLE = "named"
    ORDINAL_STYLE = "named"
    DEFAULT_STYLE = IN_STYLE

class DuplicateAnnotationError(Exception):
    """Duplicate Annotation Error."""

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if SQLParams.IN_STYLE:
        if isinstance(sql, bytes):
            sql = sql.decode('utf-8')
        params = {(k.encode('utf-8'), v.encode('utf-8')) for p in many_params for k, v in p.items()}
    else:
        params = many_params

    param_placeholders = tuple(f"?{i}" for i in range(len(params)))

    # prepare out-style parameters
    out_params = []
    for.params in params:
        out_params.append(params.values())

    # format the SQL query
    formatted_sql = sql.replace('%s', ' WHERE '.join(param_placeholders))

    return formatted_sql, out_params
