                if inventory['type'] == 'version1':
                    self.spec_version = 'version1'
                elif inventory['type'] == 'version2':
                    self.spec_version = 'version2'
                elif inventory['type'] == 'version3':
                    self.spec_version = 'version3'
        else:
            # use the version given in self.spec_version
            if not self.spec_version:
                raise ValueError("Version value cannot be empty without a type value in inventory")
    else:
        # use the version given in self.spec_version
        if not self.spec_version:
            raise ValueError("Version value cannot be empty")

