def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    if 'type' not in inventory:
        raise ValueError("Missing 'type' key in inventory following form:"
                        "inventory({'xyz': '...'}, extract_spec_version=True, ...)"
                        " must have the following keys: 'type' and 'version'")

    spec_version = inventory['type'].split('/')[1]

    if extract_spec_version:
        if spec_version not in XSD_VERSIONS:
            raise ValueError("Invalid specification version: {}".format(spec_version))
    else:
        if not spec_version:
            # infer version based on self.spec_version or give an error if not set
            if hasattr(self, 'spec_version'):
                spec_version = self.spec_version
            elif self.get('version'):
                spec_version = self.get('version')
            else:
                raise ValueError("Missing 'version' key in inventory")
        else:
            if spec_version not in XSD_VERSIONS:
                raise ValueError("Invalid specification version: {}".format(spec_version))
            if spec_version != self.get('version'):
                raise ValueError("Incompatible version in inventory and self.spec_version")

    # perform specific validation based on spec_version
    if spec_version == 'FooSpec':
        # validate FooSpec-specific attributes
        pass
    elif spec_version == 'BarSpec':
        # validate BarSpec-specific attributes
        pass

    # additional general validation
    if not 'key1' in inventory:
        raise ValueError("Missing 'key1' in inventory")
    if not 'key2' in inventory:
        raise ValueError("Missing 'key2' in inventory")
    if 'invalid_key' in inventory:
        raise ValueError("'invalid_key' is not allowed")

    return True
