    """Check all digests in manifest that are needed are present and used."""

    # Iterate through each manifest file
    for file_path in manifest_files:
        try:
            # Load the manifest file
            with open(file_path, 'r') as file:
                for line in file:
                    # Parse the line and extract the digest path
                    parts = line.strip().split()
                    if len(parts) >= 2:
                        digest_path = parts[1]
                        # Check if the digest is needed
                        if digest_path in digests_used:
                            # Stash the digest information for later use
                            self.digest_info[digest_path] = file_path
                        else:
                            print(f"Warning: Digest {digest_path} is not used in {file_path}")
                    else:
                        print(f"Warning: Invalid line format in {file_path}")
        except FileNotFoundError:
            print(f"Warning: File {file_path} not found")
