    def get_logical_path_map(self, inventory, version):
        """
        Get a map of logical paths in state to files on disk for version in inventory.

        Returns a dictionary: logical_path_in_state -> set(content_files)

        The set of content_files may includes references to duplicate files in
        later versions than the version being described.
        """
        logical_path_map = {}

        for state in inventory.stategraph:
            logical_path_map[state] = set()

        for doc in self.documents:
            logical_path_map[doc.state] = logical_path_map[doc.state].union({'/'.join(doc.path)})
            for linker in self.linkers:
                if linker.can_link(version, doc):
                    logical_path_map[doc.state] = logical_path_map[doc.state].union(linker.get_logical_path_links(version, doc))

        return logical_path_map
