    def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """

        if not isinstance(fixity, dict):
            raise ValueError("Parameter 'fixity' must be a dictionary.")

        try:
            # Check if fixity keys match the manifest files
            missing_files = [file for file in manifest_files if file not in fixity]
            if missing_files:
                raise ValueError("Missing fixity for " + ', '.join(missing_files) + ".")

            for key, fix in fixity.items():
                if not isinstance(key, str) or not isinstance(fix, dict) or not 'hash' in fix or 'size' not in fix:
                    raise ValueError("Invalid fixity entry: " + key + ". Expected a dictionary with 'hash' and 'size'.")

                expected_hash = fix['hash']
                expected_size = fix['size']
                if not expected_size:
                    raise ValueError("Invalid fixity entry: " + key + ". Size must be specified.")

                # Get the actual hash and size from the files
                actual_hash = self.hash_file(key)
                actual_size = os.path.getsize(key)

                if expected_hash != actual_hash or expected_size != actual_size:
                    raise ValueError(f"Fixity mismatch for file {key}. Expected hash {expected_hash}, got {actual_hash}. Expected size {expected_size}, got {actual_size}.")

        except Exception as e:
            raise Exception("Fixity validation failed in inventory: " + str(e))
