def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        new_args = []
        for i in args:
            for j in args:
                if i & (i | j) == i:
                    new_args.append(i)
                elif i | (i & j) == i:
                    new_args.append(i)
                elif i & (~i | j) == i & j:
                    new_args.append(i & j)
                elif i | (~i & j) == i | j:
                    new_args.append(i | j)
                else:
                    new_args.append(i)
        return list(set(new_args))  # remove duplicates
