def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    result = []
    for arg in args:
        absorbed = True
        for other in result:
            if isinstance(other, BinaryOperator) and other.op == '&':
                if isinstance(other.right, BinaryOperator) and other.right.op == '|':
                    if other.left.fluent == other.right.fluent:
                        absorbed = False
                elif isinstance(other.right, BinaryOperator) and other.right.op == '&':
                    if other.left.fluent == other.right.fluent:
                        absorbed = False
        if absorbed:
            result.append(arg)
        else:
            for other in result:
                if isinstance(other, BinaryOperator) and other.op == '&':
                    if isinstance(other.right, BinaryOperator) and other.right.op == '|':
                        if other.left.fluent == other.right.fluent:
                            result.remove(other)

    for arg in args:
        combined = []
        for other in result:
            if isinstance(other, BinaryOperator) and other.op == '&':
                if isinstance(other.right, BinaryOperator) and other.right.op == '|':
                    if other.left.fluent == other.right.fluent:
                        combined.append(BinaryOperator('|', other.left, other.right))
            elif isinstance(other, BinaryOperator) and other.op == '!=':
                if isinstance(other.right, BinaryOperator) and other.right.op == '&':
                    if other.left.fluent == other.right.fluent:
                        combined.append(BinaryOperator('!', BinaryOperator('&', other.left, other.right)))
        if combined:
            result.append(BinaryOperator('&', arg, BinaryOperator('!', BinaryOperator('&', arg, BinaryOperator('|', arg, other))))

    return result
