def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of commands to execute
    :param args: Arguments to pass to each command
    :param cwd: The working directory for the commands
    :param verbose: Whether to print verbose output
    :param hide_stderr: Whether to hide stderr output
    :param env: The environment variables to set for the commands
    """
    for i, command in enumerate(commands):
        if verbose:
            print(f"Command {i+1}: {command}")
        try:
            p = subprocess.run(command, args=args, cwd=cwd, check=True, env=env, stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL)
            if verbose:
                print(f"Command {i+1} output:\n{p.stdout.decode('utf-8')}")
        except subprocess.CalledProcessError as e:
            print(f"Command {i+1} failed: {e}")
            if verbose:
                print(f"Command {i+1} error output:\n{e.stderr.decode('utf-8')}")
