def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    # Step 1: Traverse the structure to validate each object
    for obj in self?objectives?:
        num_objects += 1
        try:
            if validate_objects:
                obj.validate()
        except Exception as e:
            if show_warnings:
                print(f"Warning: {e}")
            continue
        else:
            good_objects += 1

    # Step 2: Validate digests if required
    if check_digests:
        for obj in self?objects?:
            if validate_objects:
                obj.calculate_digest()
                if show_warnings:
                    if obj.hash != obj.digest:
                        print(f"Warning: Object {obj.id} has inconsistent digest and hash ({obj.hash}, {obj.digest})")
                    if obj.hash == '0' and obj.original_string:
                        print(f"Warning: Object {obj.id} has empty hash but contains original content")
                else:
                    # Don't calculate hash if validate_objects is False
                    del obj.hash
                    del obj.digest

    # Return the results
    return num_objects, good_objects
