def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.root_dir, version_dir, config.INVENTORY_DIR)
        try:
            with open(inventory_path, 'r') as file:
                inventory_content = file.read()
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file for version {version_dir} not found at path {inventory_path}")

        # Check if the inventory directory exists
        if not os.path.exists(inventory_path):
            raise FileNotFoundError("Inventory directory for version {version_dir} not found at path {inventory_path}")

        # Check the version number in the inventory file
        lines = inventory_content.split('\n')
        for line in lines:
            if line.startswith(config.VERSION_NUMBER_KEY):
                if line.split('=')[1].strip() != version_dir:
                    print(f"Version number in inventory for version {version_dir} does not match the version required.")
                    return
                break
        else:
            print(f"No version number found in inventory for version {version_dir}.")
            return

        # Check content digests
        content_digests = set()
        inventory_dir_contents = []
        for root, dirs, files in os.walk(inventory_path):
            for file_name in files:
                file_path = os.path.join(root, file_name)
                content_digests.add(calculate_content_digest(file_path))
                inventory_dir_contents.append(file_path)

        # Check content digests with the root inventory
        if self.root_content_digests:
            for file_path in self.root_content_digests:
                if file_path not in inventory_dir_contents:
                    print(f"The content digest for {file_path} is not found in the inventory for version {version_dir}.")
                    return

        print(f"Version {version_dir} has an inventory up to that point.")
