def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated str.

    :param parser: the argparse.ArgumentParser instance
    :return: space-separated string of argument flags
    """
    flags = []
    for action in parser._actions:
        flags.extend([f"{action.dest}"])
        for meta_key in ["nargs", "const", "metavar"]:
            if hasattr(action, meta_key):
                flags.extend([f"--{action.dest}", f"{action.{meta_key}}"])
        for dest in action.option_strings:
            flags.extend(["--" + dest.strip("-")])
        for k, v in action.choices.items():
            flags.extend([f"--{action.dest}", f"--{k}={v}"])

    return " ".join(flags)
