def deep_merge_nodes(nodes: List[Tuple[Union[str, int, float], Union[MappingNode, SequenceNode]]]) -> List[Tuple[Union[str, int, float], Union[MappingNode, SequenceNode]]]:
    # flatten the list of tuples into a list of nodes
    nodes = sum(nodes, [])

    # create a new dictionary to store the merged values
    merged_values = {}

    # iterate over the nodes and update the dictionary using the max function
    for node in nodes:
        key = node[0]
        if isinstance(node[1], MappingNode):
            for mapping_key in node[1]:
                # check if the key already exists
                if mapping_key in merged_values:
                    # if it exists, update the value using the max function
                    merged_values[mapping_key] = max(merged_values[mapping_key], mapping_value)
                elif mapping_key not in merged_values:
                    # if it doesn't exist, add the key-value pair
                    merged_values[mapping_key] = mapping_value
        else:
            # if it's not a mapping node, update the value using the max function
            merged_values[key] = max(merged_values.get(key, node[1]), node[1])

    # convert the merged dictionary back into a list of nodes
    merged_nodes = [(k, v) for k, v in merged_values.items()]

    return merged_nodes
