def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.

    """
    import argparse

    parser = argparse.ArgumentParser(
        description="Parse command-line arguments."
    )

    subparsers = parser.add_subparsers(dest="subparser_name", help="Available commands")

    for name, handler in argparse.__dict__.items():
        if callable(handler) and name.startswith("parse_"):
            subparser = subparsers.add_parser(name[6:], help=help)
            handler(subparser)
            setattr(handler, 'parser', subparser)

    options = vars(parser.parse_args(unparsed_arguments))

    global_options = {k: options.pop(k) for k in options}

    result = {k: v for k, v in global_options.items() if k != "args"}

    for subparser_name, namespace in options.items():
    if subparser_name != 'global':
        subparser = parser._subparsers.find_action_group_by_name(subparser_name)
        options = vars(namespace)
        for k, v in options.items():
            setattr(result[subparser_name], k, v)

    return result
