def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if '?' not in url:
        # No URL params found, so return early
        return url
    args_str = url[url.index('?') + 1:]
    args = {}
    for item in args_str.split('&'):
        key, value = item.split('=')
        args[key] = value

    replaced_url = url.split('?')[0]
    for key, value in args.items():
        if key in url_args:
            replaced_url = replaced_url.replace(f"{key}={url_args[key]}", f"{key}={value}")

    return replaced_url
