    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1
    if platform == 1:
        return shlex.split(s)
    elif platform == 0:
        result = []
        current = ''
        for char in s:
            if char == ' ':
                if current:
                    result.append(current)
                    current = ''
            else:
                current += char
        if current:
            result.append(current)
        return result
    else:
        raise ValueError("Unsupported platform {}. Valid values are 'this', 1, and 0.".format(platform))
