    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == 'always':
        return None

    number, unit = frequency.split()
    try:
        number = float(number)
    except ValueError:
        raise ValueError("Invalid frequency: expected a number with a unit of time, got '{}'".format(frequency))

    if unit == 'min':
        return timedelta(minutes=number)
    elif unit == 'hour':
        return timedelta(hours=number)
    elif unit == 'day':
        return timedelta(days=number)
    elif unit == 'week':
        return timedelta(weeks=number)
    elif unit == 'month':
        return timedelta(days=number * 30)
    elif unit == 'year':
        return timedelta(days=number * 365)
    else:
        raise ValueError("Invalid frequency unit: expected 'min', 'hour', 'day', 'week', 'month', or 'year', got '{}'.format(unit))
