    if frequency is None or frequency == "always":
        return None

    matches = re.match(r'(\d+) (\w+)', frequency)
    if matches is None:
        raise ValueError("Invalid frequency format: {}".format(frequency))

    number = int(matches.group(1))
    unit = matches.group(2)

    if unit == 'years':
        return datetime.timedelta(days=number * 365)
    elif unit == 'months':
        return datetime.timedelta(days=number * 30)
    elif unit == 'weeks':
        return datetime.timedelta(days=number * 7)
    elif unit == 'days':
        return datetime.timedelta(days=number)
    elif unit == 'hours':
        return datetime.timedelta(hours=number)
    elif unit == 'minutes':
        return datetime.timedelta(minutes=number)
    elif unit == 'seconds':
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError("Invalid frequency unit: {}".format(unit))

