        if s == prop or ((s, URIRef("http://www.w3.org/2000/01/rdf-schema#subClassOf"), o) and isinstance(prop, URIRef) or (s, URIRef("http://www.w3.org/2004/skos/core#broader"), o) and isinstance(prop, URIRef)):
