def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        seq_type = str
    elif isinstance(seq, bytes):
        seq_type = bytes
    elif isinstance(seq, list):
        seq_type = list
    elif isinstance(seq, dict):
        seq_type = dict
    elif isinstance(seq, bool):
        seq_type = bool
    elif isinstance(seq, int):
        seq_type = int
    else:
        # seq is actually a custom type, but we can't inspect it
        seq_type = type(seq)

    if bufsize is None:
        return seq, seq_type

    # Find the best buffer size
    optimal_buffer_size = None
    optimal_seq_type = None
    for test_size in range(1, bufsize + 1):
        if isinstance(test_size // 2, seq_type) and test_size // 4 < seq_type:
            optimal_buffer_size = test_size
            optimal_seq_type = seq_type
            break

    if optimal_buffer_size is None:
        optimal_buffer_size = bufsize
        optimal_seq_type = seq_type

    # Return a slice of the sequence
    return seq[-optimal_buffer_size:], optimal_seq_type
```

