import re
from typing import Pattern

class InStyleParameter:
    def __init__(self):
        # Initialize the regex pattern
        self.regex = re.compile(r"^\s*L(?P<argname>\w+)\s*=\s+(?P<value>.+)$", re.IGNORECASE)

    def parse(self, line):
        match = self.regex.match(line)
        if not match:
            raise ValueError(f"Invalid in-style parameter line: {line}")
        args = match.groupdict()
        return args.get("argname"), args.get("value")
