def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags_set = set()
    tag_list = []
    in_code_block = False

    for char in text:
        if char == '<':
            if not in_code_block:
                in_code_block = True
                continue
            else:
                continue
        if char == '>':
            in_code_block = False
            continue
        if in_code_block:
            continue
        if char == '{':
            stack = ['{']
        if char == '}':
            stack = []
            if stack:
                continue
        if stack:
            continue

        if char == ' ' and not in_code_block:
            if tag_list:
                tags_set.add(tuple(tag_list))
                tag_list = []
            continue

        if char == '"':
            if not tag_list:
                tag_list.append(char)
            else:
                if tag_list[-1] == '"':
                    tag_list.append(char)
                elif tag_list[-1] == '{':
                    tag_list.pop()
                    continue
                elif tag_list[-1] == '}':
                    tag_list.pop()
                    if replacer:
                        tag_list.append(replacer(tag_list[1:-1]))
                    else:
                        tag_list.append(tag_list[1:-1])
                    continue
                else:
                    tag_list.append(char)
                continue

        tag_list.append(char)

    if tag_list:
        tags_set.add(tuple(tag_list))

    return tags_set, text
```

