def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    all_tags = set()
    in_code = False
    new_text = ''

    for char in text:
        if char == '`':
            in_code = not in_code
        elif char == '[':
            in_code = True
        elif char == ']':
            in_code = False
        elif in_code:
            continue
        else:
            if char == '<':
                tag_start = text.find('<', text.index(char) + 1)
                if tag_start > -1:
                    tag_end = text.find('>', tag_start)
                    if tag_end > -1:
                        tag = text[tag_start:tag_end + 1]
                        all_tags.add(tag)
                        if replacer:
                            new_text += replacer(tag)
                        else:
                            new_text += '<' + tag + '>'
            else:
                new_text += char

    return all_tags, new_text
```

