def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # This function concatenates text links and adds some attributes to those links

    new_text = []
    links = []
    link = ""
    in_link = False

    for char in text:
        if char == '[':
            in_link = True
            link += char
        elif char == ']':
            in_link = False
            link += char
            if link:
                # Add some attributes to the link
                new_link = f"[[name='{link}', url='http://example.com']]"
                links.append(new_link)
                new_text.append(new_link)
        elif in_link:
            link += char
        else:
            new_text.append(char)

    return ''.join(new_text)
