def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    from json import dumps

    data = {
        "@context": [
            "http://www.w3.org/ns/nodeinfo/2019/09/context.jsonld",
            "http://nodeinfo.diaspora.software/2018-12/profile/context.jsonld"
        ],
        "@type": "Person",
        "name": "John Doe",
        "id": url + "/profile",
        "preferredUsername": "johndoe",
        "publicKey": {
            "mediaType": "application/json",
            "value": '{"publicKeyPem": "<KEY>"}'
        },
        "orcid": "https://orcid.org/0000-0001-2345-6789",
        "homepage": url,
        "location": {
            "latitude": 37.7749,
            "longitude": -122.4194
        },
        "newsletterPreferences": ["Bi-monthly updates", "Annual review"]
    }

    if document_path:
        data = {"@context": data, "@type": "Organization", "name": "Example Ltd."}

    return dumps(data, indent=2)
