from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    data = {}
    soup = BeautifulSoup(document, 'xml')
    if soup.find('link', rel='http://openid.net/specs/json-endpoint/1.1'):
        import json
        data = json.loads(str(soup.find('link', rel='http://openid.net/specs/json-endpoint/1.1').get('href')))
    elif soup.find('dct:Type', value='application/rdf+xml'):
        from rdflib import Graph
        g = Graph().parse(data)  # do not look at namespaces, we only need types
        types = {}
        for s, p, o in g:
            if p == 'rdfs:subClassOf':
                types[o] = s
            if p == 'dct:isPartOf':
                types[o] = p #(reversed(s))

        if types['http://xmlns.com/rdf-schema#Resource'] in data:
            data = data[types['http://xmlns.com/rdf-schema#Resource']]
        elif types['http://xmlns.com/rdf-schema#Collection'] in data:
            data = data[types['http://xmlns.com/rdf-schema#Collection']]

    return data

