from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    matches = re.findall(r'"@id": "(.+)"', document)
    if len(matches) != 1:
        return {}

    profile_url = matches[0]
    parsed_json = None
    parsed_xrd = None

    try:
        parsed_json = json.loads(document)
    except json.JSONDecodeError:
        pass

    if parsed_json:
        return parsed_json

    matches = re.findall(r'"webfinger": {"subject": "(.+)", "aliases": "(.+)"', document)
    if len(matches) == 1:
        parsed_xrd = {"subject": matches[0][0], "aliases": matches[0][1].split(",")}
        return parsed_xrd

    return {}
```

