    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not spec_option['type']:
        raise ValueError("Complex type specification must provide a type")

    arg_type = self.get_complex_argument_type(spec_option['type'])

    if arg_type:
        kwargs = {
            'delete_option': spec_option.get('delete_option') == 'yes',
            'set_option': spec_option.get('set_option') == 'yes',
            'push_mode': spec_option.get('push_mode') == 'yes'
        }
        return arg_type(**kwargs)
