import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_path = os.path.join(plugin_dir, 'spec.json')
    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"No spec.json found in {plugin_dir}")

    with open(spec_path, 'r') as spec_file:
        spec = json.load(spec_file)

    flatten_dict = {}

    def process_dict(data, parent_key=''):
        """Helper function to flatten nested dictionaries"""
        for key, value in data.items():
            if isinstance(value, dict):
                process_dict(value, parent_key + f"[{key}]")
            elif isinstance(value, list):
                for sub_index, sub_value in enumerate(value):
                    process_dict(sub_value, parent_key + f"[{key}][{sub_index}]")
            elif "*" in key:
                # Support key ending with "*" for modules
                module = key.replace("*", "")
                if module not in flatten_dict:
                    flatten_dict[module] = {}
                process_dict(data, f"{parent_key}.{module}")
            else:
                flatten_dict[parent_key] = data

    process_dict(spec)

    return flatten_dict
